function WardrobeApp({ token, onLogout }) {
    const [clothingItems, setClothingItems] = useState([]);
    const [activeCategory, setActiveCategory] = useState('All');
    const [isAddModalOpen, setIsAddModalOpen] = useState(false);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [activeDepartment, setActiveDepartment] = useState('Men');

    const authHeader = { 'Authorization': `Bearer ${token}` };

    useEffect(() => {
        const fetchItems = async () => {
            try {
                setIsLoading(true);
                const response = await fetch(`${API_BASE_URL}/api/items`, { headers: authHeader });
                if (!response.ok) throw new Error('Failed to fetch data from the server.');
                const data = await response.json();
                setClothingItems(data);
                setError(null);
            } catch (err) {
                setError(err.message);
            } finally {
                setIsLoading(false);
            }
        };
        fetchItems();
    }, [token]);

    const categoryCounts = useMemo(() => {
        const counts = {};
        const currentCategories = departmentData[activeDepartment] || [];

        currentCategories.flatMap(cat => cat.subCategories).forEach(subCat => {
            counts[subCat] = 0;
        });

        clothingItems.forEach(item => {
            if (item.department === activeDepartment && !item.inLaundry && counts[item.category] !== undefined) {
                counts[item.category]++;
            }
        });

        currentCategories.forEach(mainCat => {
            counts[mainCat.name] = mainCat.subCategories.reduce((sum, subCat) => sum + (counts[subCat] || 0), 0);
        });

        counts['All'] = clothingItems.filter(item => item.department === activeDepartment && !item.inLaundry).length;

        return counts;
    }, [clothingItems, activeDepartment]);

    const filteredItems = useMemo(() => {
        let items = clothingItems;
        items = items.filter(item => item.department === activeDepartment);
        if (activeCategory === 'Laundry') {
            items = items.filter(item => item.inLaundry);
        } else if (activeCategory !== 'All') {
            const mainCategory = departmentData[activeDepartment]?.find(cat => cat.name === activeCategory);
            if (mainCategory) {
                 items = items.filter(item => !item.inLaundry && mainCategory.subCategories.includes(item.category));
            } else {
                 items = items.filter(item => !item.inLaundry && item.category === activeCategory);
            }
        } else {
            items = items.filter(item => !item.inLaundry);
        }
        if (searchTerm.trim() !== '') {
            items = items.filter(item => 
                item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                (item.brand && item.brand.toLowerCase().includes(searchTerm.toLowerCase()))
            );
        }
        return items;
    }, [clothingItems, activeCategory, searchTerm, activeDepartment]);

    const handleAddItem = async (newItem) => {
        try {
            const response = await fetch(`${API_BASE_URL}/api/items`, {
                method: 'POST',
                headers: { ...authHeader, 'Content-Type': 'application/json' },
                body: JSON.stringify(newItem)
            });
            if (!response.ok) throw new Error('Failed to add item.');
            const savedItem = await response.json();
            setClothingItems(prev => [...prev, savedItem]);
            setIsAddModalOpen(false);
        } catch (err) { console.error("Add item error:", err); }
    };
    const toggleLaundryStatus = async (itemToUpdate) => {
        const updatedItem = { ...itemToUpdate, inLaundry: !itemToUpdate.inLaundry };
        try {
            await fetch(`${API_BASE_URL}/api/items/${itemToUpdate.id}`, {
                method: 'PUT',
                headers: { ...authHeader, 'Content-Type': 'application/json' },
                body: JSON.stringify(updatedItem)
            });
            setClothingItems(items => items.map(item => item.id === itemToUpdate.id ? updatedItem : item));
        } catch (err) { console.error("Update laundry error:", err); }
    };
    const clearLaundry = async () => {
        const itemsToWash = clothingItems.filter(item => item.inLaundry);
        try {
            await Promise.all(itemsToWash.map(item =>
                fetch(`${API_BASE_URL}/api/items/${item.id}`, {
                    method: 'PUT',
                    headers: { ...authHeader, 'Content-Type': 'application/json' },
                    body: JSON.stringify({ ...item, inLaundry: false })
                })
            ));
            setClothingItems(items => items.map(item => item.inLaundry ? { ...item, inLaundry: false } : item));
        } catch (err) { console.error("Clear laundry error:", err); }
    };
    const deleteItem = async (itemId) => {
        try {
            await fetch(`${API_BASE_URL}/api/items/${itemId}`, { method: 'DELETE', headers: authHeader });
            setClothingItems(items => items.filter(item => item.id !== itemId));
        } catch (err) { console.error("Delete item error:", err); }
    };

    return (
        <div className="flex flex-col h-screen">
            <Header 
                onAddItem={() => setIsAddModalOpen(true)} 
                onMenuClick={() => setSidebarOpen(!sidebarOpen)} 
                onLogout={onLogout}
                searchTerm={searchTerm}
                setSearchTerm={setSearchTerm}
                activeDepartment={activeDepartment}
                setActiveDepartment={setActiveDepartment}
                activeCategory={activeCategory}
                setActiveCategory={setActiveCategory}
                categoryCounts={categoryCounts}
            />
            <div className="flex flex-1 overflow-hidden">
                <FilterSidebar 
                    activeCategory={activeCategory} setActiveCategory={setActiveCategory}
                    isOpen={sidebarOpen} setIsOpen={setSidebarOpen}
                    clearLaundry={clearLaundry} laundryCount={clothingItems.filter(i => i.inLaundry && i.department === activeDepartment).length}
                    activeDepartment={activeDepartment}
                    setActiveDepartment={setActiveDepartment}
                    categoryCounts={categoryCounts}
                />
                <MainContent 
                    items={filteredItems}
                    onToggleLaundry={toggleLaundryStatus} onDeleteItem={deleteItem}
                    isLoading={isLoading} error={error} 
                />
            </div>
            {isAddModalOpen && <AddItemModal onClose={() => setIsAddModalOpen(false)} onAddItem={handleAddItem} />}
        </div>
    );
}
